<?php
namespace App\Livewire\Attendance;
use App\Models\AttendanceEntry; use App\Models\Employee; use App\Models\Shift; use App\Services\AttendanceService; use Carbon\Carbon; use Livewire\Component;
class Index extends Component { public ?int $employeeId=null;public string $punchType='in';public string $punchAt='';public string $shiftCode='';public string $shiftName='';public string $shiftStart='09:00';public string $shiftEnd='17:00';public function mount():void{$this->punchAt=now()->format('Y-m-d\TH:i');} public function createShift():void{$this->authorize('manage-hr');$d=$this->validate(['shiftCode'=>'required|string|max:50','shiftName'=>'required|string|max:255','shiftStart'=>'required','shiftEnd'=>'required']);Shift::create(['code'=>$d['shiftCode'],'name'=>$d['shiftName'],'start_time'=>$d['shiftStart'],'end_time'=>$d['shiftEnd'],'working_days'=>[1,2,3,4,5]]);$this->reset('shiftCode','shiftName');} public function punch(AttendanceService $s):void{$this->authorize('manage-hr');$d=$this->validate(['employeeId'=>'required|exists:employees,id','punchType'=>'required|in:in,out','punchAt'=>'required|date']);try{$s->recordPunch(Employee::findOrFail($d['employeeId']),$d['punchType'],Carbon::parse($d['punchAt']),'manual');}catch(\RuntimeException $e){$this->addError('attendance',$e->getMessage());}} public function approve(int $id,AttendanceService $s):void{$this->authorize('manage-hr');$s->approve(AttendanceEntry::findOrFail($id),auth()->id());} public function render(){return view('livewire.attendance.index',['employees'=>Employee::orderBy('name')->get(),'shifts'=>Shift::where('active',true)->orderBy('code')->get(),'entries'=>AttendanceEntry::with(['employee','shift'])->latest('work_date')->limit(100)->get()]);} }
